r\nfunction saveLoc() {\r\n  const name = locSelect.value === '__custom__' ? locCustom.value.trim() : locSelect.value.trim();\r\n  if (name) {\r\n    emit('updateLocation', name);\r\n  }\r\n  isEditingLoc.value = false;\r\n  locSelect.value = '';\r\n  locCustom.value = '';\r\n}\r\n\r\nfunction cancelEditLoc() {\r\n  isEditingLoc.value = false;\r\n  locSelect.value = '';\r\n  locCustom.value = '';\r\n}\r\n\r\n// 别名编辑\r\nconst isEditingAliases = ref(false);\r\nconst editingAliasesText = ref('');\r\n\r\nfunction startEditAliases() {\r\n  editingAliasesText.value = (props.aliases || []).join('、');\r\n  isEditingAliases.value = true;\r\n}\r\n\r\nfunction saveAliases() {\r\n  if (!props.characterName) return;\r\n  const newAliases = editingAliasesText.value.split(/[,，、/]/).map(s => s.trim()).filter(Boolean);\r\n  const ok = store.updateCharacterAliases(props.characterName, newAliases);\r\n  if (ok) {\r\n    isEditingAliases.value = false;\r\n  }\r\n}\r\n\r\nfunction cancelEditAliases() {\r\n  isEditingAliases.value = false;\r\n}\r\n\r\nwatch(() => props.characterName, () => {\r\n  isEditingAliases.value = false;\r\n});\r\n</script>\r\n\r\n<style scoped>\r\n.sheet-header {\r\n  display: flex;\r\n  gap: 12px;\r\n  align-items: flex-start;\r\n}\r\n.sheet-avatar {\r\n  width: 56px;\r\n  height: 56px;\r\n  border-radius: 50%;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-size: 22px;\r\n  font-weight: 600;\r\n  flex-shrink: 0;\r\n  user-select: none;\r\n}\r\n.sheet-info {\r\n  flex: 1;\r\n  min-width: 0;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 4px;\r\n}\r\n.sheet-top {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  flex-wrap: wrap;\r\n}\r\n.sheet-name {\r\n  font-size: 16px;\r\n  font-weight: 600;\r\n  color: var(--zn-text-primary);\r\n}\r\n.sheet-attitude {\r\n  font-size: 10px;\r\n  padding: 1px 6px;\r\n  border-radius: 10px;\r\n  font-weight: 500;\r\n}\r\n.sheet-attitude.like {\r\n  background: rgba(var(--zn-success-rgb), 0.15);\r\n  color: rgba(var(--zn-success-rgb), 0.9);\r\n}\r\n.sheet-attitude.dislike {\r\n  background: rgba(var(--zn-danger-rgb), 0.15);\r\n  color: rgba(var(--zn-danger-rgb), 0.9);\r\n}\r\n.sheet-attitude.neutral {\r\n  background: var(--zn-bg-surface2);\r\n  color: var(--zn-text-muted);\r\n}\r\n.sheet-aliases {\r\n  font-size: 11px;\r\n  color: var(--zn-text-secondary);\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  flex-wrap: wrap;\r\n}\r\n.sheet-location-row {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  font-size: 12px;\r\n  flex-wrap: wrap;\r\n}\r\n.sheet-location-label {\r\n  color: var(--zn-text-muted);\r\n}\r\n.sheet-location-value {\r\n  color: var(--zn-text-primary);\r\n  font-weight: 500;\r\n}\r\n.sheet-loc-brief {\r\n  font-size: 11px;\r\n  color: var(--zn-text-secondary);\r\n  line-height: 1.4;\r\n  max-width: 100%;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  display: -webkit-box;\r\n  -webkit-line-clamp: 2;\r\n  -webkit-box-orient: vertical;\r\n}\r\n.sheet-loc-btn {\r\n  font-size: 10px;\r\n  padding: 1px 7px;\r\n  border-radius: 4px;\r\n  border: 1px solid var(--zn-border-light);\r\n  background: var(--zn-bg-surface2);\r\n  color: var(--zn-text-secondary);\r\n  cursor: pointer;\r\n}\r\n.sheet-loc-btn:hover {\r\n  color: var(--zn-accent);\r\n  border-color: var(--zn-accent);\r\n}\r\n.sheet-loc-save {\r\n  background: rgba(var(--zn-accent-rgb), 0.12);\r\n  color: var(--zn-accent);\r\n}\r\n.sheet-loc-select,\r\n.sheet-loc-input {\r\n  background: var(--zn-bg-surface2);\r\n  border: 1px solid var(--zn-border-light);\r\n  border-radius: var(--zn-radius-sm);\r\n  padding: 3px 6px;\r\n  color: var(--zn-text-primary);\r\n  font-size: 12px;\r\n  min-width: 120px;\r\n}\r\n.sheet-loc-select:focus,\r\n.sheet-loc-input:focus {\r\n  border-color: var(--zn-accent);\r\n  outline: none;\r\n}\r\n.sheet-loc-input {\r\n  flex: 1;\r\n  max-width: 180px;\r\n}\r\n.sheet-alias-input {\r\n  flex: 1 1 200px;\r\n  min-width: 160px;\r\n  max-width: 100%;\r\n  background: var(--zn-bg-surface2);\r\n  border: 1px solid var(--zn-border-light);\r\n  border-radius: var(--zn-radius-sm);\r\n  padding: 3px 6px;\r\n  color: var(--zn-text-primary);\r\n  font-size: 11px;\r\n  box-sizing: border-box;\r\n}\r\n.sheet-alias-input:focus {\r\n  border-color: var(--zn-accent);\r\n  outline: none;\r\n}\r\n</style>\r\n"],"sourceRoot":""}]);
